do $test$
declare u uuid:=gen_random_uuid();price integer;s jsonb;op uuid;balance integer;stock integer;
begin
 insert into auth.users(id) values(u);
 insert into public.player_profiles(id,nickname) values(u,'일괄미끼'||left(u::text,6));
 perform set_config('request.jwt.claim.sub',u::text,true);
 insert into public.player_wallets(user_id,gold,inventory) values(u,1000000,'{"bait":0}') on conflict(user_id) do update set gold=1000000,inventory=excluded.inventory;
 select b.price into price from public.fishing_baits b where id='bait';
 op:=gen_random_uuid();
 set local role authenticated;
 s:=public.buy_fishing_bait_bulk('bait',30,op,price);
 if (s->>'gold')::integer<>1000000-price*30 or (s#>>'{inventory,bait}')::integer<>30 or (s->>'delta')::integer<>-price*30 then raise exception 'BULK_TOTAL_WRONG';end if;
 s:=public.buy_fishing_bait_bulk('bait',30,op,price);
 if (s->>'delta')::integer<>0 or not (s->>'replayed')::boolean or (s#>>'{inventory,bait}')::integer<>30 then raise exception 'BULK_RETRY_CHARGED';end if;
 begin perform public.buy_fishing_bait_bulk('bait',29,op,price);raise exception 'QUANTITY_CONFLICT_ALLOWED';exception when others then if sqlerrm<>'OPERATION_CONFLICT' then raise;end if;end;
 begin perform public.buy_fishing_bait_bulk('bait',30,op,price+1);raise exception 'PRICE_CONFLICT_ALLOWED';exception when others then if sqlerrm<>'OPERATION_CONFLICT' then raise;end if;end;
 begin perform public.buy_fishing_bait_bulk('bait',0,gen_random_uuid(),price);raise exception 'ZERO_ALLOWED';exception when others then if sqlerrm<>'INVALID_QUANTITY' then raise;end if;end;
 begin perform public.buy_fishing_bait_bulk('bait',100,gen_random_uuid(),price);raise exception 'OVER_LIMIT_ALLOWED';exception when others then if sqlerrm<>'INVALID_QUANTITY' then raise;end if;end;
 begin perform public.buy_fishing_bait_bulk('bait',2,gen_random_uuid(),price+1);raise exception 'STALE_PRICE_ALLOWED';exception when others then if sqlerrm<>'BAIT_PRICE_CHANGED' then raise;end if;end;
 reset role;
 if (select count(*) from public.gold_transactions where user_id=u)<>1 or (select count(*) from app_private.bait_purchase_operations where user_id=u)<>1 then raise exception 'LEDGER_NOT_SINGLE';end if;
 update public.player_wallets set gold=price*2-1 where user_id=u;
 set local role authenticated;
 begin perform public.buy_fishing_bait_bulk('bait',2,gen_random_uuid(),price);raise exception 'PARTIAL_BUY_ALLOWED';exception when others then if sqlerrm<>'INSUFFICIENT_GOLD' then raise;end if;end;
 reset role;
 if (select gold from public.player_wallets where user_id=u)<>price*2-1 or (select (inventory->>'bait')::integer from public.player_wallets where user_id=u)<>30 then raise exception 'PARTIAL_CHANGE';end if;
 update public.player_wallets set gold=1000000 where user_id=u;
 insert into app_private.player_fishing_relics(user_id,relic_id) values(u,'sea-king-trade-ledger');
 set local role authenticated;
 perform public.equip_relic('sea-king-trade-ledger',gen_random_uuid(),0);
 op:=gen_random_uuid();
 s:=public.buy_fishing_bait_bulk('bait',99,op,greatest(1,price-2));
 if (s->>'gold')::integer<>1000000-greatest(1,price-2)*99 or (s#>>'{inventory,bait}')::integer<>129 then raise exception 'BULK_DISCOUNT_WRONG';end if;
 perform public.equip_relic(null,gen_random_uuid(),500);
 s:=public.buy_fishing_bait_bulk('bait',99,op,greatest(1,price-2));
 if (s->>'delta')::integer<>0 or (s#>>'{inventory,bait}')::integer<>129 then raise exception 'RETRY_REPRICED';end if;
 begin perform 1 from app_private.bait_purchase_operations;raise exception 'RECEIPT_READ_ALLOWED';exception when insufficient_privilege then null;end;
 reset role;
 update public.player_wallets set inventory=jsonb_set(inventory,'{bait}','1000000000') where user_id=u;
 set local role authenticated;
 begin perform public.buy_fishing_bait_bulk('bait',1,gen_random_uuid(),price);raise exception 'STOCK_LIMIT_ALLOWED';exception when others then if sqlerrm<>'INVENTORY_LIMIT' then raise;end if;end;
 reset role;
 set local role anon;
 begin perform public.buy_fishing_bait_bulk('bait',1,gen_random_uuid(),price);raise exception 'ANON_BUY_ALLOWED';exception when insufficient_privilege then null;end;
 reset role;
end $test$;
